<?php
require_once __DIR__ . '/../config/database.php';
$where=["status='available'"]; $params=[];
if(!empty($_GET['type'])){$where[]='room_type=?';$params[]=$_GET['type'];}
if(isset($_GET['min'])&&$_GET['min']!==''){$where[]='price>=?';$params[]=(float)$_GET['min'];}
if(isset($_GET['max'])&&$_GET['max']!==''){$where[]='price<=?';$params[]=(float)$_GET['max'];}
if(isset($_GET['guests'])&&$_GET['guests']!==''){$where[]='capacity>=?';$params[]=(int)$_GET['guests'];}
$stmt=$pdo->prepare('SELECT * FROM rooms WHERE '.implode(' AND ',$where).' ORDER BY price');$stmt->execute($params);$rooms=$stmt->fetchAll();$pageTitle='Rooms & Suites | LUMIÈRE';$activePage='rooms';require __DIR__ . '/../includes/header.php';
?><section class="page-hero"><div><div class="eyebrow">Your own little world</div><h1>Rooms & Suites</h1></div></section><section class="content-wrap"><form class="filter-bar" method="get"><div class="form-field"><label>Room style</label><select name="type"><option value="">All room styles</option><?php foreach(['Deluxe Room','Premium Room','Executive Suite','Presidential Suite'] as $t): ?><option <?= ($_GET['type']??'')===$t?'selected':'' ?>><?= e($t) ?></option><?php endforeach; ?></select></div><div class="form-field"><label>From (₹)</label><input type="number" name="min" value="<?= e($_GET['min']??'') ?>" min="0" placeholder="Any"></div><div class="form-field"><label>To (₹)</label><input type="number" name="max" value="<?= e($_GET['max']??'') ?>" min="0" placeholder="Any"></div><div class="form-field"><label>Guests</label><select name="guests"><option value="">Any number</option><?php for($i=1;$i<=6;$i++): ?><option value="<?= $i ?>" <?= (($_GET['guests']??'')==(string)$i)?'selected':'' ?>><?= $i ?> guests</option><?php endfor; ?></select></div><button class="button">Find a room</button></form><div class="room-grid"><?php foreach($rooms as $r): ?><article class="room-card"><a class="room-card-image" href="room-details.php?id=<?= (int)$r['room_id'] ?>"><img src="<?= e($r['image']) ?>" alt="<?= e($r['room_name']) ?>"></a><div class="room-card-body"><div class="eyebrow"><?= e($r['room_type']) ?></div><h3><?= e($r['room_name']) ?></h3><p><?= e($r['description']) ?></p><div class="room-meta"><span><?= e($r['bed_type']) ?> · up to <?= (int)$r['capacity'] ?></span><span>₹<?= number_format((float)$r['price']) ?> / night</span></div><a class="text-link" href="room-details.php?id=<?= (int)$r['room_id'] ?>">View details →</a> <a class="text-link" href="<?= url('booking.php') ?>?room_id=<?= (int)$r['room_id'] ?>">Book →</a></div></article><?php endforeach; ?><?php if(!$rooms): ?><p>No rooms match these filters. Try a wider search.</p><?php endif; ?></div></section><?php require __DIR__ . '/../includes/footer.php'; ?>
